INSERT INTO irResearchProject (id, title, status, budgetInitial, budgetSpent, startDate, endDate, leaderId, department, createdAt, updatedAt)
VALUES ('54c98f8f-d83b-4bad-89d0-26ed0be409dd', 'การศึกษาชนิดภาคตัดขวางเพื่อศึกษาความสัมพันธ์ทางเภสัชจลศาสตร์ของขนาดยา  คอลจิซีนที่มีการใช้ในเวชปฏิบัติคลินิกในการป้องกันการเกิดข้ออักเสบกำเริบในผู้ป่วยโรคเกาต์ที่มีภาวะไตวายระยะต่าง ๆ ร่วมด้วย (A corss-sectional study to determine the association between the dosage of colchicine and its pharmacokinetic profiles in real practice, and in gouty arthritis patients with varying degrees of renal impairment)', 'APPROVED', 193000.0, 0.0, '2023-12-22T00:00:00.000Z', '2025-12-21T00:00:00.000Z', 'user-1', 'Faculty of Medicine', datetime('now'), datetime('now'));
INSERT INTO irResearchProject (id, title, status, budgetInitial, budgetSpent, startDate, endDate, leaderId, department, createdAt, updatedAt)
VALUES ('b37c2487-f5d2-43cf-a50e-54b067f40ff3', 'ข้อเสนอเพื่อการพัฒนาการให้บริการผู้สูงอายุของโรงพยาบาลส่งเสริมสุขภาพตำบลในสังกัดขององค์การบริหารส่วนจังหวัดพิษณุโลก', 'ONGOING', 798000.0, 0.0, '2023-10-01T00:00:00.000Z', '2024-09-30T23:59:59.000Z', 'user-1', 'Faculty of Medicine', datetime('now'), datetime('now'));
INSERT INTO irResearchProject (id, title, status, budgetInitial, budgetSpent, startDate, endDate, leaderId, department, createdAt, updatedAt)
VALUES ('572483a6-d35a-46ac-a163-ba03dfa21830', 'แคมเบรีย-1 (CAMBRIA-1): การศึกษาวิจัยระยะที่ 3 แบบเปิดเผยข้อมูลยา แบบสุ่ม เพื่อประเมินประสิทธิผลและความปลอดภัยของการบำบัดรักษาแบบขยายด้วยยาคามิเซสแทรนท์ [เอแซดดี9833 (AZD9833) ยาสลายตัวรับฮอร์โมนเอสโตรเจนแบบเจาะจงชนิดรับประทานรุ่นถัดไป] เทียบกับการรักษาด้วยวิธีฮอร์โมนมาตรฐาน (ยายับยั้งเอนไซม์อะโรมาเทสหรือยาทาม็อกซิเฟน) ในผู้ป่วยโรคมะเร็งเต้านมระยะเริ่มแรกที่มีอีอาร์เป็นบวก/เฮอร์ทูเป็นลบ ( ER+/HER2-) และมีความเสี่ยงในการกลับมาเป็นซ้ำในระดับปานกลางหรือระดับสูงที่ได้รับการบำบัดรักษาหลักแบบเฉพาะที่เสร็จสมบูรณ์แล้ว และได้รับการรักษาเสริมหลังการผ่าตัดด้วยวิธีฮอร์โมนมาตรฐานอย่างน้อย 2 ปีโดยไม่มีการกลับมาเป็นซ้ำของโรค', 'ONGOING', 1042100.0, 0.0, '2023-10-01T00:00:00.000Z', '2024-09-30T23:59:59.000Z', 'user-1', 'Faculty of Medicine', datetime('now'), datetime('now'));